import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import {
  cameraDrift,
  hardCut,
} from "../transitions";
import {
  SPRINGS,
  TIMING,
  springIn,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

const COLORS = {
  text: BRAND.colors.text, // #f4f4f5
};

// 25fps. Slide THROUGH every year 2004 → 2014, then linger on 2014.
const SLIDE_FRAMES = 40;   // time it takes to scroll through all the years
const LINGER_FRAMES = 90;  // linger on 2014

export const fps = 25;
export const durationInFrames = SLIDE_FRAMES + LINGER_FRAMES;

const TRANSITION = Math.max(1, Math.round(fps / 25));

const START_YEAR = 2004;
const END_YEAR = 2014;

// Build the full list of years: [2004, 2005, ..., 2014]
const YEARS: number[] = [];
for (let y = START_YEAR; y <= END_YEAR; y++) YEARS.push(y);
const LAST_INDEX = YEARS.length - 1; // index that lands in the center = 2014

const CounterScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const numberSize = base * 0.24;
  // Horizontal spacing between each year in the filmstrip.
  const step = base * 0.55;

  // Progress 0 → 1: 0 = first year (2004) centered, 1 = last year (2014) centered.
  // easeInOut so it accelerates through the middle years and settles on 2014.
  const scrollProgress = interpolate(frame, [0, SLIDE_FRAMES], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });

  // The strip's X offset: slide left by one `step` per year of progress.
  const stripX = -scrollProgress * LAST_INDEX * step;

  // Ambient breathing during the linger — never freeze.
  const driftY = ambientDrift(frame, 3, 90, "year-y");
  const driftX = ambientDrift(frame, 2, 110, "year-x");
  const driftScale = 1 + ambientDrift(frame, 0.004, 120, "year-s");

  // Center window width — clips so you see roughly one year at a time.
  const windowW = step * 0.95;

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Center viewport window that clips the scrolling strip. */}
      <div
        style={{
          position: "relative",
          width: windowW,
          height: numberSize * 1.4,
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `translate(${driftX}px, ${driftY}px) scale(${driftScale})`,
        }}
      >
        {/* The filmstrip: all years in a horizontal row, sliding left. */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            display: "flex",
            alignItems: "center",
            transform: `translate(calc(-50% + ${stripX}px), -50%)`,
          }}
        >
          {YEARS.map((year, i) => {
            // Distance of this year from the current center position (in steps).
            const centerPos = scrollProgress * LAST_INDEX;
            const dist = Math.abs(i - centerPos);
            // Fade + shrink years as they move away from center for depth.
            const opacity = interpolate(dist, [0, 0.5, 1], [1, 0.35, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const scale = interpolate(dist, [0, 1], [1, 0.82], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            return (
              <div
                key={year}
                style={{
                  width: step,
                  flexShrink: 0,
                  textAlign: "center",
                  fontFamily: "'GT Walsheim', Inter, sans-serif",
                  fontWeight: 600,
                  fontSize: numberSize,
                  color: COLORS.text,
                  letterSpacing: "-0.03em",
                  lineHeight: 1,
                  fontVariantNumeric: "tabular-nums",
                  opacity,
                  transform: `scale(${scale})`,
                  textShadow:
                    "0 12px 48px rgba(0,0,0,0.55), 0 4px 16px rgba(0,0,0,0.4)",
                }}
              >
                {year}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  const { fps: vfps, durationInFrames: total } = useVideoConfig();
  const camera = cameraDrift(useCurrentFrame(), total);

  return (
    <AbsoluteFill
      style={{ transform: camera.transform, transformOrigin: "50% 50%" }}
    >
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={durationInFrames}>
          <CounterScene />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </AbsoluteFill>
  );
};

export default MainComposition;
